<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount,onMounted} from 'vue'
import {getCurrentWindow} from '@tauri-apps/api/window'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {useAuth} from '../stores/auth'
import {useDatabase} from '../stores/database'
import {command,message,desktop} from '../api'
import {date,localDate} from '../format'
import type {Study,Patient,FieldValue,FieldDefinition} from '../types'
import catalogData from '../catalog.json'
import {renderLegacy,resolveValue} from '../legacy'
import {calculateLegacy,calculationDependencies,calculatedKeys,invalidateCalculations} from '../calculations'
import versionsData from '../legacy-versions.json'
import TemplateLibrary from '../components/TemplateLibrary.vue'
import {appendTemplate,type UserTemplate} from '../userTemplates'
import ProtocolDocument from '../components/ProtocolDocument.vue'
import Attachments from '../components/Attachments.vue'
import StructuredFields from '../components/StructuredFields.vue'
import PageHeading from '../components/PageHeading.vue'
const showLibrary=ref(false),insertTarget=ref('conclusion')
const insertTargets=computed(()=>[{label:'Заключение',value:'conclusion'},{label:'Дополнение и рекомендации',value:'addition'},{label:'Свободное описание',value:'description'},...definitions.value.filter(d=>d.kind==='get'||d.kind.includes('TextArea')).map(d=>({label:d.label,value:d.key}))])
function insertTemplate(entry:UserTemplate){const text=entry.value||entry.name;if(insertTarget.value==='conclusion')conclusion.value=appendTemplate(conclusion.value,text);else if(insertTarget.value==='addition')addition.value=appendTemplate(addition.value,text);else updateField(insertTarget.value,appendTemplate(fields.value[insertTarget.value]?.value||'',text));success.value='Заготовка добавлена. Проверьте текст и сохраните исследование.';showLibrary.value=false}
const versions=versionsData as Record<string,string>
const templateVersion=ref('1'),showAllFields=ref(false)
const catalog=catalogData as Record<string,FieldDefinition[]>
const route=useRoute(),router=useRouter(),db=useDatabase(),auth=useAuth()
const record=ref<Study>(),patient=ref<Patient>(),templateId=ref<number>(),doctorId=ref<number>(),studyDate=ref(localDate()),conclusion=ref(''),addition=ref(''),fields=ref<Record<string,FieldValue>>({}),status=ref('draft'),error=ref(''),saving=ref(false),loading=ref(false),snapshot=ref(''),confirmLeave=ref(false),discardAction=ref<null|(()=>void)>(null),success=ref(''),showFields=ref(true)
const isArchive=computed(()=>record.value?.origin==='legacy')
const readonly=computed(()=>!auth.canWrite||Boolean(record.value&&!isArchive.value&&auth.user?.role==='doctor'&&record.value.doctor_id!==auth.user.doctorId)),isNew=computed(()=>!route.params.id)
const currentTemplate=computed(()=>db.info?.templates.find(t=>t.id===templateId.value))
const definitions=computed(()=>{
  const code=currentTemplate.value?.code.toLowerCase();if(!code)return []
  const key=code+'_'+templateVersion.value
  if(catalog[key])return catalog[key]
  return []
})
const additionalDefinitions=computed<FieldDefinition[]>(()=>{const known=new Set(definitions.value.map(d=>d.key));return Object.entries(fields.value).filter(([key])=>key!=='description'&&!key.startsWith('_')&&!known.has(key)).map(([key,value])=>({key,label:key,kind:'get',valueType:value.type}))})
const templateItems=computed(()=>{const items=db.info?.templates.map(t=>({label:t.name,value:t.id}))||[];if(record.value&&!items.some(t=>t.value===record.value!.template_id))items.unshift({label:record.value.title||'Вид исследования не указан',value:record.value.template_id});return items})
const doctorItems=computed(()=>{const items=db.info?.doctors.map(d=>({label:d.name,value:d.id}))||[];if(record.value&&!items.some(d=>d.value===record.value!.doctor_id))items.unshift({label:record.value.doctor||'Врач не указан',value:record.value.doctor_id});return items})
const rendered=computed(()=>renderLegacy(currentTemplate.value?.code||record.value?.templateCode||'',templateVersion.value,fields.value))
const hasStructuredData=computed(()=>definitions.value.some(d=>Boolean(fields.value[d.key]?.value)))
const useRendered=computed(()=>rendered.value.supported&&!rendered.value.unknownValues.length&&(readonly.value||hasStructuredData.value))
const activeDefinitions=computed(()=>showAllFields.value||!rendered.value.supported?definitions.value:definitions.value.filter(d=>rendered.value.activeFields.includes(d.key)))
const calculationCode=computed(()=>currentTemplate.value?.code.toLowerCase()||'')
const calculationPending=computed(()=>fields.value._calculation_pending?.value==='1')
const canCalculate=computed(()=>['shit','eho_kg','ginekol','brooho'].includes(currentTemplate.value?.code.toLowerCase()||''))
function recalculate(){try{Object.assign(fields.value,calculateLegacy(currentTemplate.value?.code||'',fields.value));delete fields.value._calculation_pending;error.value='';success.value='Расчёт выполнен по формулам исходной программы. Проверьте результат перед сохранением.'}catch(e){error.value=message(e)}}
const visibleFields=computed(()=>{
  const byKey=new Map(definitions.value.map(d=>[d.key,d]))
  return Object.entries(fields.value).filter(([key,v])=>!key.startsWith('_')&&v.value).map(([key,v])=>({key,label:byKey.get(key)?.label||key,value:resolveValue(v)}))
})
const formState=()=>JSON.stringify([templateId.value,doctorId.value,studyDate.value,conclusion.value,addition.value,fields.value,status.value,templateVersion.value])
const dirty=computed(()=>!readonly.value&&snapshot.value!==''&&formState()!==snapshot.value)
watch(()=>route.fullPath,load,{immediate:true})
async function load(){loading.value=true;error.value='';success.value='';snapshot.value='';record.value=undefined;patient.value=undefined;fields.value={};conclusion.value='';addition.value='';studyDate.value=localDate();status.value='draft';templateId.value=undefined;doctorId.value=auth.user?.role==='doctor'?auth.user.doctorId||undefined:undefined
 try{if(!db.info)await db.load();if(route.params.id){const s=await command<Study>('study_detail',{id:Number(route.params.id)});record.value=s;templateVersion.value=s.legacy_version||'1';templateId.value=s.template_id;doctorId.value=s.doctor_id;studyDate.value=s.date.slice(0,10);conclusion.value=s.conclusion;addition.value=s.addition;fields.value=s.fields;status.value=s.status;if(s.patient_id){try{const p=await command<{patient:Patient}>('patient_detail',{id:s.patient_id});patient.value=p.patient}catch(e){if(!message(e).includes('Пациент не найден'))throw e}}}else{const p=await command<{patient:Patient}>('patient_detail',{id:Number(route.params.patientId)});patient.value=p.patient}snapshot.value=formState();if(isNew.value&&route.query.from){const source=await command<Study>('study_detail',{id:Number(route.query.from)});if(source.patient_id!==patient.value?.id)throw new Error('Исходное исследование относится к другому пациенту');templateId.value=source.template_id;templateVersion.value=source.legacy_version||'1';doctorId.value=auth.user?.role==='doctor'?auth.user.doctorId||undefined:source.doctor_id;conclusion.value=source.conclusion;addition.value=source.addition;fields.value=source.fields;if(calculationDependencies[calculationCode.value]?.some(key=>fields.value[key]?.value))invalidateCalculations(calculationCode.value,fields.value)}}catch(e){error.value=message(e)}finally{loading.value=false}}
function updateField(key:string,value:string,type?:string){if(fields.value[key]?.value===value)return;fields.value[key]={value,type:type||fields.value[key]?.type||'text'};if(calculationDependencies[calculationCode.value]?.includes(key))invalidateCalculations(calculationCode.value,fields.value)}
const confirmTemplate=ref(false),pendingTemplate=ref<number>()
function requestTemplate(value:number){if(value===templateId.value)return;if(Object.entries(fields.value).some(([key,v])=>key!=='description'&&v.value)){pendingTemplate.value=value;confirmTemplate.value=true}else{pendingTemplate.value=value;changeTemplate()}}
function changeTemplate(){const description=fields.value.description;fields.value=description?{description}:{};templateId.value=pendingTemplate.value;const code=db.info?.templates.find(t=>t.id===templateId.value)?.code.toLowerCase()||'';templateVersion.value=versions[code]||'1';confirmTemplate.value=false}
let unlistenClose:(()=>void)|undefined
onMounted(async()=>{if(desktop)unlistenClose=await getCurrentWindow().onCloseRequested(event=>{if(dirty.value){event.preventDefault();discardAction.value=()=>{void getCurrentWindow().destroy()};confirmLeave.value=true}})})
onBeforeUnmount(()=>unlistenClose?.())
async function save(nextStatus:string){saving.value=true;error.value='';success.value='';try{const id=await command<number>('save_study',{input:{id:record.value?.id??null,revision:record.value?.revision??null,patientId:patient.value?.id??record.value?.patient_id,templateId:templateId.value,doctorId:doctorId.value,date:studyDate.value,conclusion:conclusion.value,addition:addition.value,fields:fields.value,status:nextStatus,templateVersion:templateVersion.value}});snapshot.value=formState();await db.load();if(isNew.value)await router.replace('/studies/'+id);else await load();success.value=nextStatus==='final'?'Исследование завершено и сохранено':'Черновик сохранён'}catch(e){error.value=message(e)}finally{saving.value=false}}
async function copy(){const s=record.value;if(s)await router.push('/studies/new/'+s.patient_id+'?from='+s.id)}
onBeforeRouteLeave((_to,_from,next)=>{if(!dirty.value){next();return}discardAction.value=()=>next();confirmLeave.value=true})
function cancelLeave(){discardAction.value=null;confirmLeave.value=false}
function discard(){snapshot.value=formState();discardAction.value?.();confirmLeave.value=false;discardAction.value=null}
function unload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
const print=()=>window.print()
</script>
<template><section class="page-content study-page"><RouterLink v-if="patient" :to="'/patients/'+patient.id" class="back-link no-print"><UIcon name="i-lucide-arrow-left"/>К карточке пациента</RouterLink><PageHeading :title="readonly?'Просмотр исследования':isNew?'Новое исследование':'Редактирование исследования'" :description="patient?.name||record?.patientName"><template v-if="readonly"><UButton color="neutral" variant="outline" icon="i-lucide-copy-plus" @click="copy" :disabled="!desktop||!auth.canWrite||!patient">Создать на основе</UButton><UButton icon="i-lucide-printer" @click="print">Печать</UButton></template><template v-else><UBadge v-if="dirty" color="warning" variant="subtle">Есть изменения</UBadge><UButton color="neutral" variant="outline" :disabled="saving||!desktop||!auth.canWrite||loading" :loading="saving" @click="save('draft')">Сохранить черновик</UButton><UButton icon="i-lucide-check" :disabled="saving||!desktop||!auth.canWrite||loading" @click="save('final')">Завершить</UButton></template></PageHeading>
<UAlert v-if="calculationPending" color="warning" variant="soft" title="Расчёт не выполнен" description="Размеры изменились, прежние вычисленные значения удалены. Можно завершить и распечатать исследование без расчёта. Для расчёта заполните необходимые размеры и нажмите «Пересчитать»." class="mb-5 no-print"/><UAlert v-if="error" color="error" :description="error" class="mb-5 no-print"/><UAlert v-if="rendered.unknownValues.length" color="warning" title="Часть значений отсутствует в исходном справочнике" description="Показаны сохранённые параметры. Печатный текст для этой записи требует проверки." class="mb-5 no-print"/><UAlert v-if="!rendered.supported&&(currentTemplate||readonly)" color="warning" title="Для этой версии шаблона доступны сохранённые параметры" description="Точное формирование связного текста пока не поддерживается." class="mb-5 no-print"/><UAlert v-if="success" color="success" variant="soft" :description="success" class="mb-5 no-print"/>
<div v-if="loading" class="loading-state">Открываем исследование…</div><template v-else-if="patient||record||readonly">
<div class="study-layout" :class="{'readonly-layout':readonly}">
<aside v-if="!readonly" class="study-settings no-print" aria-labelledby="study-settings-title">
  <h2 id="study-settings-title">Об исследовании</h2>
  <div class="study-settings-fields">
    <UFormField label="Вид исследования" required><USelect :model-value="templateId" :items="templateItems" placeholder="Выберите исследование" class="w-full" @update:model-value="requestTemplate"/></UFormField>
    <UFormField label="Врач" required><USelect :disabled="auth.user?.role==='doctor'&&!isArchive" v-model="doctorId" :items="doctorItems" placeholder="Выберите врача" class="w-full"/></UFormField>
    <UFormField label="Дата исследования" required><UInput v-model="studyDate" type="date" class="w-full"/></UFormField>
  </div>
  <UButton icon="i-lucide-book-open" variant="outline" class="study-template-button" @click="showLibrary=true">Справочник шаблонов</UButton>
</aside>
<ProtocolDocument v-if="readonly&&record" :study="record"/><article v-else class="document-sheet"><div class="document-header"><span class="document-brand"><UIcon name="i-lucide-activity"/>Протокол исследования</span><span>{{date(studyDate)}}<template v-if="record"> · № {{record.id}}</template></span></div><h2>{{currentTemplate?.name||record?.title||'Выберите вид исследования'}}</h2><dl class="document-patient"><div><dt>Пациент</dt><dd>{{patient?.name||record?.patientName||'Без карточки пациента'}}</dd></div><div><dt>Дата рождения</dt><dd>{{date(patient?.birthdate||record?.patientBirthdate)}}</dd></div><div><dt>Врач</dt><dd>{{db.info?.doctors.find(d=>d.id===doctorId)?.name||record?.doctor||'Не выбран'}}</dd></div></dl>
<p v-if="calculationCode==='shit'" class="print-unit-note">В исходном шаблоне объём обозначен как «мм». Обозначения сохранены для сопоставления с архивом. При размерах в миллиметрах исходная формула рассчитывает объём в см³.</p>
<p v-if="record?.status==='draft'||record?.status==='legacy:0'" class="print-unit-note">ЧЕРНОВИК. Исследование не завершено.</p><p v-if="calculationPending" class="print-unit-note">Вычисленные значения удалены после изменения размеров. Расчёт не выполнен.</p>
<template v-if="readonly"><section v-if="useRendered" class="document-section legacy-protocol" v-html="rendered.html"></section><section v-else-if="visibleFields.length" class="document-section"><h3>Сохранённые параметры исследования</h3><dl class="archive-fields"><div v-for="field in visibleFields" :key="field.key"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl></section><section class="document-section"><h3>Заключение</h3><p class="preserve-lines">{{conclusion||'Заключение не заполнено'}}</p></section><section v-if="addition" class="document-section"><h3>Дополнение</h3><p class="preserve-lines">{{addition}}</p></section><p v-if="isArchive" class="archive-print-note">{{rendered.supported&&!rendered.unknownValues.length?'Архивная запись. Содержание сформировано по исходному шаблону; оформление адаптировано для A4.':'Архивная запись. Показаны сохранённые параметры; связный текст для этой версии требует проверки.'}}</p></template>
<template v-else><div class="print-only"><section class="document-section"><h3>Описание исследования</h3><div v-if="useRendered" class="legacy-protocol" v-html="rendered.html"></div><p class="preserve-lines">{{fields.description?.value}}</p><dl v-if="!useRendered" class="archive-fields"><div v-for="field in visibleFields.filter(f=>f.key!=='description')" :key="field.key"><dt>{{field.label}}</dt><dd>{{field.value}}</dd></div></dl></section><section class="document-section"><h3>Заключение</h3><p class="preserve-lines">{{conclusion}}</p></section><section v-if="addition" class="document-section"><h3>Дополнение</h3><p class="preserve-lines">{{addition}}</p></section></div><section class="document-section no-print"><h3>Описание исследования</h3><UFormField label="Протокол" description="Свободное описание результатов исследования"><UTextarea :model-value="fields.description?.value||''" @update:model-value="updateField('description',$event)" :rows="8" autoresize class="w-full" placeholder="Опишите результаты исследования…"/></UFormField></section><section v-if="definitions.length" class="document-section no-print"><button class="field-toggle" @click="showFields=!showFields" :aria-expanded="showFields"><UIcon :name="showFields?'i-lucide-chevron-down':'i-lucide-chevron-right'"/>Поля исходного шаблона <span>{{definitions.length}}</span></button><template v-if="showFields"><div class="flex items-center justify-between gap-4 flex-wrap mb-5"><UCheckbox v-model="showAllFields" label="Показать все поля шаблона"/><UButton v-if="canCalculate" icon="i-lucide-calculator" variant="outline" @click="recalculate">Пересчитать</UButton></div><p v-if="canCalculate" class="calculation-units">{{calculationCode==='eho_kg'?'Размеры для расчёта — в см.':'Размеры для расчёта — в мм.'}}</p><StructuredFields :readonly-keys="calculatedKeys[calculationCode]||[]" :definitions="activeDefinitions" :fields="fields" @change="updateField"/><section v-if="useRendered" class="document-section"><h3>Предпросмотр протокола</h3><div class="legacy-protocol" v-html="rendered.html"></div></section></template></section><section v-if="additionalDefinitions.length" class="document-section no-print"><h3>Сохранённые параметры</h3><StructuredFields :definitions="additionalDefinitions" :fields="fields" @change="updateField"/></section><section class="document-section no-print"><UFormField label="Заключение" required><UTextarea v-model="conclusion" :rows="5" autoresize class="w-full" placeholder="Введите заключение…"/></UFormField></section><section class="document-section no-print"><UFormField label="Дополнение и рекомендации"><UTextarea v-model="addition" :rows="3" autoresize class="w-full" placeholder="При необходимости"/></UFormField></section><div v-if="record" class="flex justify-end no-print"><UButton variant="ghost" color="neutral" icon="i-lucide-printer" @click="print" :disabled="dirty">Печать сохранённой записи</UButton></div></template>
<footer class="document-signature"><span>Врач: {{db.info?.doctors.find(d=>d.id===doctorId)?.name||record?.doctor||'________________'}}</span><span>Подпись __________________</span></footer>
</article></div><Attachments v-if="record" :study-id="record.id" :editable="!readonly&&auth.canWrite&&desktop"/></template>
<UModal v-model:open="showLibrary" title="Справочник шаблонов" description="Выберите, куда добавить заготовку. Уже введённый текст сохранится." :ui="{content:'sm:max-w-3xl'}"><template #body><UFormField label="Куда вставить" class="mb-5"><USelect v-model="insertTarget" :items="insertTargets" class="w-full"/></UFormField><TemplateLibrary :template-id="templateId" pick @select="insertTemplate"/></template></UModal>
<UModal v-model:open="confirmTemplate" title="Сменить вид исследования?" description="Заполненные поля прежнего шаблона будут удалены. Свободное описание, заключение и рекомендации сохранятся."><template #footer><UButton color="neutral" variant="outline" @click="confirmTemplate=false">Оставить прежний вид</UButton><UButton color="warning" @click="changeTemplate">Сменить и очистить поля</UButton></template></UModal>
<UModal :open="confirmLeave" @update:open="cancelLeave" title="Остались несохранённые изменения" description="Сохраните исследование или выйдите без сохранения."><template #footer><UButton color="neutral" variant="outline" @click="cancelLeave">Продолжить редактирование</UButton><UButton color="error" @click="discard">Выйти без сохранения</UButton></template></UModal>
</section></template>

